tool_input_args.value:
awk -F',' 'NR>1 && $6~/^2026-0[789]/ {
  total += $5; count++
  if ($7=="won")   { won += $5; won_c++ }
  if ($7=="lost")  { lost += $5; lost_c++ }
  if ($7=="pending") { pend += $5; pend_c++ }
}
END {
  printf "All deals:     %d deals, $%'\''d\n", count, total
  printf "Won deals:     %d deals, $%'\''d\n", won_c, won
  printf "Lost deals:    %d deals, $%'\''d\n", lost_c, lost
  printf "Pending deals: %d deals, $%'\''d\n", pend_c, pend
  printf "Win rate:      %.1f%%\n", (won_c/count)*100
}' data/sales_q3.csv
